import { type NextRequest } from 'next/server';
import { db } from '@/lib/db';

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const { id } = await params;
  const fields = request.nextUrl.searchParams.get('fields');

  const product = await db.product.findUnique({ where: { id } });
  if (!product) {
    return Response.json({ error: 'Produto não encontrado' }, { status: 404 });
  }
  return Response.json(fields === 'basic' ? { id: product.id, name: product.name } : product);
}

import * as z from 'zod';
import { revalidateTag } from 'next/cache';
import { db } from '@/lib/db';

const ProductInput = z.object({
  name: z.string().trim().min(1),
  price: z.number().positive(),
});

export async function POST(request: Request) {
  const body = await request.json().catch(() => null);
  const result = ProductInput.safeParse(body);
  if (!result.success) {
    return Response.json({ errors: z.flattenError(result.error).fieldErrors }, { status: 400 });
  }

  const product = await db.product.create({ data: result.data });
  revalidateTag('products', 'max');
  return Response.json(product, { status: 201 });
}

'use server';

import * as z from 'zod';
import { updateTag } from 'next/cache';
import { verifySession } from '@/lib/dal';
import { db } from '@/lib/db';

const ProductInput = z.object({
  name: z.string().trim().min(1, { error: 'Informe o nome.' }),
  price: z.coerce.number().positive({ error: 'O preço precisa ser maior que zero.' }),
});

export type FormState = { errors?: Record<string, string[] | undefined> } | undefined;

export async function createProduct(_prev: FormState, formData: FormData): Promise<FormState> {
  const { userId } = await verifySession();

  const result = ProductInput.safeParse({
    name: formData.get('name'),
    price: formData.get('price'),
  });
  if (!result.success) {
    return { errors: z.flattenError(result.error).fieldErrors };
  }

  await db.product.create({ data: { ...result.data, ownerId: userId } });
  updateTag('products');
  return {};
}

'use client';

import { useActionState } from 'react';
import { createProduct } from '../actions';

export function ProductForm() {
  const [state, formAction, pending] = useActionState(createProduct, undefined);

  return (
    <form action={formAction}>
      <input name="name" />
      {state?.errors?.name && <p>{state.errors.name[0]}</p>}

      <input name="price" inputMode="decimal" />
      {state?.errors?.price && <p>{state.errors.price[0]}</p>}

      <button disabled={pending}>{pending ? 'Salvando...' : 'Salvar'}</button>
    </form>
  );
}

import 'server-only';

import { cache } from 'react';
import { cookies } from 'next/headers';
import { redirect } from 'next/navigation';
import { decrypt } from '@/lib/session';
import { db } from '@/lib/db';

export const verifySession = cache(async () => {
  const token = (await cookies()).get('session')?.value;
  const session = await decrypt(token);
  if (!session?.userId) redirect('/login');
  return { userId: session.userId };
});

export async function getProject(projectId: string) {
  const { userId } = await verifySession();
  const project = await db.project.findUnique({ where: { id: projectId } });
  if (!project || project.ownerId !== userId) return null;
  return { id: project.id, name: project.name };
}

import { NextResponse, type NextRequest } from 'next/server';
import { decrypt } from '@/lib/session';

const publicRoutes = ['/login', '/signup'];

export async function proxy(request: NextRequest) {
  const isPublic = publicRoutes.includes(request.nextUrl.pathname);
  const session = await decrypt(request.cookies.get('session')?.value);

  if (!isPublic && !session?.userId) {
    return NextResponse.redirect(new URL('/login', request.nextUrl));
  }
  if (isPublic && session?.userId) {
    return NextResponse.redirect(new URL('/dashboard', request.nextUrl));
  }
  return NextResponse.next();
}

